package android.os;import java.util.*;public class Bundle{private final Map<String,Object> data=new HashMap<>();public Bundle(){}public Bundle(Bundle other){data.putAll(other.data);}public Object get(String k){return data.get(k);}public boolean containsKey(String k){return data.containsKey(k);}public void putInt(String k,int v){data.put(k,v);}public void putLong(String k,long v){data.put(k,v);}public void putDouble(String k,double v){data.put(k,v);}public void putFloat(String k,float v){data.put(k,v);}public void putBoolean(String k,boolean v){data.put(k,v);}public void putString(String k,String v){data.put(k,v);}public String getString(String k){return getString(k,null);}public String getString(String k,String f){Object v=data.get(k);return v instanceof String?(String)v:f;}public boolean getBoolean(String k,boolean f){Object v=data.get(k);return v instanceof Boolean?(Boolean)v:f;}public long getLong(String k,long f){Object v=data.get(k);return v instanceof Number?((Number)v).longValue():f;}}
